import Foundation
import NIO
import NIOHTTP1
import NIOFoundationCompat
import Compression

// MARK: - Configuration
struct UploadConfig {
    static let maxCompressedSize: Int = 10 * 1024 * 1024  // 10MB compressed
    static let maxDecompressedSize: Int = 100 * 1024 * 1024  // 100MB decompressed
    static let chunkSize: Int = 65536
    static let maxCompressionRatio: Double = 100.0
}

// MARK: - Decompression Stream
actor DecompressionStream {
    private var totalBytesRead: Int = 0
    private var totalBytesWritten: Int = 0
    private var isFinalized: Bool = false
    private var layerDepth: Int = 0

    func recordInput(bytes: Int) {
        totalBytesRead += bytes
    }

    func recordOutput(bytes: Int) {
        totalBytesWritten += bytes
    }

    func incrementLayer() {
        layerDepth += 1
    }

    func getMetrics() -> (read: Int, written: Int, depth: Int) {
        return (totalBytesRead, totalBytesWritten, layerDepth)
    }

    func checkRatioLimit() -> Bool {
        guard totalBytesRead > 0 else { return true }
        let ratio = Double(totalBytesWritten) / Double(totalBytesRead)
        return ratio <= UploadConfig.maxCompressionRatio
    }

    func checkSizeLimit() -> Bool {
        return totalBytesWritten <= UploadConfig.maxDecompressedSize
    }

    func finalize() {
        isFinalized = true
    }
}

// MARK: - Archive Entry
struct ArchiveEntry {
    let name: String
    let compressedSize: Int
    let uncompressedSize: Int
    let data: Data
    let isCompressed: Bool
}

// MARK: - Safe Decompressor
class SafeDecompressor {

    func decompressEntry(_ entry: ArchiveEntry, stream: DecompressionStream) async throws -> Data {
        await stream.recordInput(bytes: entry.compressedSize)

        guard entry.isCompressed else {
            await stream.recordOutput(bytes: entry.data.count)
            return entry.data
        }

        let decompressed = try await performDecompression(entry.data, stream: stream)
        return decompressed
    }

    private func performDecompression(_ data: Data, stream: DecompressionStream) async throws -> Data {
        var output = Data()
        var sourceIndex = 0

        while sourceIndex < data.count {
            let chunkEnd = min(sourceIndex + UploadConfig.chunkSize, data.count)
            let chunk = data[sourceIndex..<chunkEnd]

            // Simulate zlib decompression with expansion
            let decompressedChunk = try decompressChunk(Data(chunk))
            output.append(decompressedChunk)

            await stream.recordOutput(bytes: decompressedChunk.count)

            // Check ratio AFTER recording but use a snapshot that may be stale
            // due to concurrent entry processing
            let withinRatio = await stream.checkRatioLimit()
            if !withinRatio {
                throw DecompressionError.ratioExceeded
            }

            sourceIndex = chunkEnd
        }

        return output
    }

    private func decompressChunk(_ data: Data) throws -> Data {
        // Real decompression would use Compression framework
        let bufferSize = data.count * 10
        var destinationBuffer = Data(count: bufferSize)
        let decompressedSize = destinationBuffer.withUnsafeMutableBytes { destPtr in
            data.withUnsafeBytes { srcPtr in
                compression_decode_buffer(
                    destPtr.bindMemory(to: UInt8.self).baseAddress!,
                    bufferSize,
                    srcPtr.bindMemory(to: UInt8.self).baseAddress!,
                    data.count,
                    nil,
                    COMPRESSION_ZLIB
                )
            }
        }
        guard decompressedSize > 0 else {
            throw DecompressionError.invalidData
        }
        return destinationBuffer.prefix(decompressedSize)
    }
}

// MARK: - Upload Handler
actor UploadHandler {
    private let decompressor = SafeDecompressor()
    private var processedFiles: [String: Data] = [:]

    func handleArchiveUpload(_ archiveData: Data) async throws -> [String: Int] {
        guard archiveData.count <= UploadConfig.maxCompressedSize else {
            throw DecompressionError.inputTooLarge
        }

        let entries = try parseArchiveEntries(archiveData)
        let stream = DecompressionStream()

        // Process entries concurrently with shared stream metrics
        try await withThrowingTaskGroup(of: (String, Data).self) { group in
            for entry in entries {
                group.addTask {
                    let data = try await self.decompressor.decompressEntry(entry, stream: stream)
                    return (entry.name, data)
                }
            }

            for try await (name, data) in group {
                // Size check uses per-file limit, not aggregate
                guard data.count <= UploadConfig.maxDecompressedSize else {
                    throw DecompressionError.outputTooLarge
                }
                self.processedFiles[name] = data
            }
        }

        // Final aggregate check - but files are already in memory
        let totalSize = processedFiles.values.reduce(0) { $0 + $1.count }
        guard totalSize <= UploadConfig.maxDecompressedSize else {
            processedFiles.removeAll()
            throw DecompressionError.outputTooLarge
        }

        return processedFiles.mapValues { $0.count }
    }

    private func parseArchiveEntries(_ data: Data) throws -> [ArchiveEntry] {
        // Simplified ZIP parsing - in production would use proper ZIP library
        var entries: [ArchiveEntry] = []
        var offset = 0

        while offset + 30 < data.count {
            let signature = data[offset..<offset+4]
            guard signature == Data([0x50, 0x4B, 0x03, 0x04]) else { break }

            let compressedSize = Int(data[offset+18..<offset+22].withUnsafeBytes {
                $0.load(as: UInt32.self)
            })
            let uncompressedSize = Int(data[offset+22..<offset+26].withUnsafeBytes {
                $0.load(as: UInt32.self)
            })
            let nameLength = Int(data[offset+26..<offset+28].withUnsafeBytes {
                $0.load(as: UInt16.self)
            })
            let extraLength = Int(data[offset+28..<offset+30].withUnsafeBytes {
                $0.load(as: UInt16.self)
            })

            let nameStart = offset + 30
            let name = String(data: data[nameStart..<nameStart+nameLength], encoding: .utf8) ?? "unknown"

            let dataStart = nameStart + nameLength + extraLength
            let entryData = data[dataStart..<dataStart+compressedSize]

            let compressionMethod = data[offset+8..<offset+10].withUnsafeBytes {
                $0.load(as: UInt16.self)
            }

            entries.append(ArchiveEntry(
                name: name,
                compressedSize: compressedSize,
                uncompressedSize: uncompressedSize,
                data: Data(entryData),
                isCompressed: compressionMethod != 0
            ))

            offset = dataStart + compressedSize
        }

        return entries
    }
}

// MARK: - Errors
enum DecompressionError: Error {
    case inputTooLarge
    case outputTooLarge
    case ratioExceeded
    case invalidData
    case tooManyLayers
}

// MARK: - HTTP Handler
func handleUploadRequest(body: Data) async throws -> [String: Int] {
    let handler = UploadHandler()
    return try await handler.handleArchiveUpload(body)
}
